package com.yigongbao.backup.admin;
import cn.dev33.satoken.stp.StpUtil; import com.fasterxml.jackson.databind.ObjectMapper; import com.yigongbao.backup.cleanup.CleanupDryRunJobHandler; import com.yigongbao.backup.cleanup.CleanupExecuteJobHandler; import com.yigongbao.backup.common.ApiResponse; import com.yigongbao.backup.job.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.UUID;
/** 管理员 COS 清理试运行和授权消费接口。 */
@RestController @RequestMapping("/api/v1/admin/cleanup") @RequiredArgsConstructor
public class AdminCleanupController { private final PersistentJobCoordinator jobs; private final ObjectMapper mapper; private static String rid(){return UUID.randomUUID().toString();} @PostMapping("/dry-runs") public ApiResponse<JobTask> dry(@RequestBody DryRun c)throws Exception{StpUtil.checkRole("ADMIN");if(c==null||c.olderThanDays()<0)throw new IllegalArgumentException("清理周期非法");return create("CLEANUP_DRY_RUN",new CleanupDryRunJobHandler.Payload(c.olderThanDays()));} @PostMapping("/permit-poll") public ApiResponse<JobTask> execute(@RequestBody Permit c)throws Exception{StpUtil.checkRole("ADMIN");if(c==null||c.taskId()==null||c.taskId().isBlank())throw new IllegalArgumentException("清理任务标识不能为空");return create("CLEANUP_EXECUTE",new CleanupExecuteJobHandler.Payload(c.taskId()));} private ApiResponse<JobTask> create(String type,Object payload)throws Exception{long actor=StpUtil.getLoginIdAsLong();String json=mapper.writeValueAsString(payload);JobEntity j=jobs.create(type,JobIdempotency.key(type,actor,json),actor,json);return ApiResponse.ok(new JobTask(j.getId(),j.getJobNo(),j.getStatus()),rid());} public record DryRun(int olderThanDays){} public record Permit(String taskId){} public record JobTask(Long jobId,String jobNo,String status){} }
